(* [comment removed for export] *)
Definition kd_ok (c : CC.cutpoint) : bool :=
  has (CC.cp_know c) (KDisj (SA FE 0) (ELit 512) (SA RE 0) (ELit 592)) && has (CC.cp_know c) (KDisj (SA FE 0) (ELit 512) (SA ISE 0) (ELit 272)) && has (CC.cp_know c) (KDisj (SA FE 0) (ELit 512) (SA VE 0) (ELit 8)).
Definition leaf_chk (i : nat) (c : CC.cutpoint) (k : nat) (ps : SR.post_spec) (t : CC.tag) : bool :=
  match t with
  | CC.TGoto _ _ => false
  | CC.TOther pc =>
      let cells := SR.ps_cells ps in
      match CH2.ret_of G.RETS i k with
      | Some j =>
          match nth_error G.CPS j with
          | Some cj =>
              (Nat.eqb j (i + 1) && CH2.blocks_eqb (nth i G.BLS []) (BLKS i) && CH2.blocks_eqb (nth j G.BLS []) (BLKS j) && CHA.frames_eqb (nth i FFS []) (if Nat.eqb i 0 then [] else FRM)
               && CHA.frames_eqb (nth j FFS []) FRM && CHA.foot_chk GT.NF G.HDECL c (BLKS i) (nth i FFS []) && (Nat.eqb i 0 || ((Nat.eqb i 18 || fsh_ok cells) && kd_ok c && Nat.leb 46 (CC.cp_nx c) && CBA.regions_eqb (CC.cp_F c) CPF)) && CH2.blocks_vars_lt (CC.cp_nx c) (BLKS i) &&
              if Z.eqb pc PC_SM3 then
                (Z.eqb (SR.ps_pc ps) PC_SM3 && Nat.eqb i 0
                 && match CHA.custom_chk GT.NF G.HDECL GT.SCELLS GT.GLO GT.GHI 512 1 [] [] [] (NEWS_SM ps cj) None c ps cj [] [] [] FRM with
                    | Some ci => (Nat.eqb (CH2.ci_nx ci) 40 && Z.eqb (CH2.ci_csp ci) (-160))%bool | None => false end)%bool
              else if Z.eqb pc PC_AMEMSET || Z.eqb pc PC_MEMSET then
                match MSITE i with
                | Some (pcx, base, off, n) =>
                    (Z.eqb (SR.ps_pc ps) pcx && Z.eqb pc pcx
                     && isSome (CHA.custom_chk GT.NF G.HDECL GT.SCELLS GT.GLO GT.GHI 2560 0 (BLKS i) FRM [(EAlu Instr.ALU_ADD base (ELit off), 0, ELit n)] (NEWS_MS base off n) (Some (EAlu Instr.ALU_ADD base (ELit off))) c ps cj (BLKS i) FRM (BLKS j) FRM)
                     && CL.ps_reg_is ps 10 (EAlu Instr.ALU_ADD base (ELit off)) && CL.ps_reg_is ps 11 (ELit 0) && CL.ps_reg_is ps 12 (ELit n)
                     && has cells (KZero (SA (CHA.SRL3 RE) SBz) (ELit 74)) && has cells (KWord (SA FE 504) 8 FLE))%bool
                | None => false
                end
              else if Z.eqb pc PC_LOCALE then
                match LOCSITE i with
                | Some off =>
                    (Z.eqb (SR.ps_pc ps) PC_LOCALE
                     && isSome (CHA.custom_chk GT.NF G.HDECL GT.SCELLS GT.GLO GT.GHI 64 0 (BLKS i) FRM [(IA off, 0, ELit 8)] (NEWS_LOC off) None c ps cj (BLKS i) FRM (BLKS j) FRM)
                     && CL.ps_reg_is ps 10 (IA off) && has cells (KWord (SA FE 504) 8 FLE))%bool
                | None => false
                end
              else if Z.eqb pc PC_OPNEW then
                let nx := (CC.cp_nx cj - APC.NCS)%nat in let news := news_of (nx + 4) cj in
                (Z.eqb (SR.ps_pc ps) PC_OPNEW && Nat.eqb i 8 && Nat.eqb nx 170
                 && isSome (CHA.custom_chk GT.NF G.HDECL GT.SCELLS GT.GLO GT.GHI 4112 0 [] FRM [] (news ++ FRNEWS ++ FLAGN) None c ps cj [] FRM (BLKS 9) FRM)
                 && CRB.fresh_news_ok 65536 7094272 G.HDECL GT.SCELLS GT.GLO GT.GHI cells nx [] FRM (nx + 4) (ELit 16384) news
                 && CL.ps_reg_is ps 10 (ELit 16384) && has cells (KWord (SA FE 504) 8 FLE))%bool
              else if Z.eqb pc PC_AMEMCPY then
                match MCSITE i with
                | Some (doff, soff) =>
                    (Z.eqb (SR.ps_pc ps) PC_AMEMCPY
                     && isSome (CHA.custom_chk GT.NF G.HDECL GT.SCELLS GT.GLO GT.GHI 2560 0 (BLKS i) FRM [(IA doff, 0, ELit 24)] (NEWS_MS RE doff 24) (Some (IA doff)) c ps cj (BLKS i) FRM (BLKS j) FRM)
                     && CL.ps_reg_is ps 10 (IA doff) && CL.ps_reg_is ps 11 (IAF soff) && CL.ps_reg_is ps 12 (ELit 24)
                     && has cells (KZero (SA (CHA.SRL3 RE) SBz) (ELit 74)) && has cells (KZero (SA FE 112) (ELit 144)) && has cells (KWord (SA FE 504) 8 FLE))%bool
                | None => false
                end
              else if Z.eqb pc PC_STRRES then
                let nx := (CC.cp_nx cj - APC.NCS - 1)%nat in let news := news_of nx cj in
                (Z.eqb (SR.ps_pc ps) PC_STRRES && Nat.eqb i 15 && Nat.eqb nx 282
                 && isSome (CHA.custom_chk GT.NF G.HDECL GT.SCELLS GT.GLO GT.GHI 4368 1 (BLKS 15) FRM [(IA 544, 0, ELit 24)] (news ++ FRNEWS ++ NEWS_STR ++ STAT) None c ps cj (BLKS 15) FRM (BLKS 16) FRM)
                 && CL.ps_reg_is ps 10 (IA 544) && CL.ps_reg_is ps 11 (ELit 256)
                 && has cells (KZero (SA RE 544) (ELit 24)) && has cells (KZero (SA RE 568) (ELit 24))
                 && has cells (KZero (SA (CHA.SRL3 RE) SBz) (ELit 74)) && has cells (KWord (SA FE 504) 8 FLE))%bool
              else if Z.eqb pc PC_VECRES then
                let nx := (CC.cp_nx cj - APC.NCS - 1)%nat in let news := news_of nx cj in
                (Z.eqb (SR.ps_pc ps) PC_VECRES && Nat.eqb i 16 && Nat.eqb nx 299
                 && isSome (CHA.custom_chk GT.NF G.HDECL GT.SCELLS GT.GLO GT.GHI 8192 1 (BLKS 16) FRM [(IA 568, 0, ELit 24)] (news ++ FRNEWS ++ NEWS_VEC ++ STAT) None c ps cj (BLKS 16) FRM (BLKS 17) FRM)
                 && CL.ps_reg_is ps 10 (IA 568) && CL.ps_reg_is ps 11 (ELit 66) && has cells (KZero (SA RE 568) (ELit 24))
                 && has cells (KZero (SA (CHA.SRL3 RE) SBz) (ELit 74)) && has cells (KWord (SA FE 504) 8 FLE))%bool
              else if Z.eqb pc PC_VPUSH then
                (Z.eqb (SR.ps_pc ps) PC_VPUSH && Nat.eqb i 17
                 && isSome (CHA.custom_chk GT.NF G.HDECL GT.SCELLS GT.GLO GT.GHI 8240 0 (BLKS 16) FRM [(IA 568, 0, ELit 24)] NEWS_PUSH None c ps cj (BLKS 17) FRM (BLKS 18) FRM)
                 && CL.ps_reg_is ps 10 (IA 568) && CL.ps_reg_is ps 11 (EAlu Instr.ALU_ADD (EVar 2) (ELit (-321))) && CL.ps_reg_is ps 2 (EAlu Instr.ALU_ADD (EVar 2) (ELit (-336)))
                 && has cells (KWord (SA RE 568) 8 BE) && has cells (KWord (SA RE 576) 8 BE) && has cells (KWord (SA RE 584) 8 (EAlu Instr.ALU_ADD BE (ELit 66)))
                 && has cells (KWord (SA (EVar 2) (-321)) 1 (ELit 0)) && has cells (KZero (SA (CHA.SRL3 RE) SBz) (ELit 74)) && has cells (KWord (SA FE 504) 8 FLE))%bool
              else if Z.eqb pc PC_SETSH then
                (Z.eqb (SR.ps_pc ps) PC_SETSH && Nat.eqb i 18
                 && match CHA.custom_chk GT.NF G.HDECL GT.SCELLS GT.GLO GT.GHI 256 0 (BLKS 18) FRM [(CHA.SRL3 FE, SBz, ELit 64)] (STAT ++ FLAGN) None c ps cj (BLKS 18) FRM (BLKS 19) FRM with
                    | Some ci => (Z.eqb (CH2.ci_csp ci) (-160) && Nat.leb (CC.cp_nx c) (CH2.ci_nx ci))%bool | None => false end
                 && CL.ps_reg_is ps 10 (EAlu Instr.ALU_ADD (CHA.SRL3 FE) (ELit SBz)) && CL.ps_reg_is ps 11 (ELit 64) && has cells (KWord (SA FE 504) 8 FLE))%bool
              else false)%bool
          | None => false
          end
      | None =>
         ((((Z.eqb pc DEAD1 && has cells (DEADF 16)) || (Z.eqb pc DEAD2 && has cells (DEADF 32))) && Nat.eqb i 10)   (* [comment removed for export] *)
         ||
          (Z.eqb pc RETPC && Nat.eqb i 19 && CBA.exit_base_chk GT.NF RETPC c ps && CBA.regions_eqb (CC.cp_F c) CPF18 && CH2.blocks_eqb (nth i G.BLS []) (BLKS 19)
           && CHA.frames_eqb (nth i FFS []) FRM
           && match CHA.retire_chk GT.NF G.HDECL c (BLKS 19) FRM with Some fl => expr_eqb fl FLE | None => false end
           && has cells (KWord (SA FLE 0) 1 (ELit 0)) && CL.ps_reg_is ps 10 FLE
           && exit_cells cells && kd_ok c && Nat.leb 46 (CC.cp_nx c) && CH2.blocks_vars_lt (CC.cp_nx c) (BLKS 19)))%bool
      end
  end.
